Value.Calculation:
epSQLExecute (
	"SELECT Nivelacija.Status, Nivelacija.NacinIzmjene, Nivelacija.BrojNivelacije" &
	" FROM Nivelacija WHERE Nivelacija.PrimaryKey = ?" ;
	"useSQLResult=rs_hdr" ;
	$nivelacijaId
)

epSQLExecute (
	"INSERT INTO StavkeNivelacije" &
	" ( PrimaryKey, ForeignKeyNivelacijaID, ForeignKeyStavkaPrimkeID, ForeignKeyArtikalID," &
	"   ForeignKeyKalkulacijaID, RedniBroj, Sifra, Naziv, JM, KolicinaNaStanju," &
	"   NabavnaCijenaEfektivna, NacinIzmjene," &
	"   StaraMPCijena, StaraMPCijenaBezPDV, StariPDVPostotak, StariPDVIznos, StariRUCIznos," &
	"   NovaMPCijena, NovaMPCijenaBezPDV, NoviPDVPostotak, NoviPDVIznos, NoviRUCIznos," &
	"   StaraVrijednost, StaraVrijednostBezPDV, NovaVrijednost, NovaVrijednostBezPDV," &
	"   RazlikaVrijednost, RazlikaRUC, RazlikaPDV )" &
	" VALUES ( ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ? )" ;
	"" ;
	$stavkaId ;
	$nivelacijaId ;
	$batchId ;
	JSONGetElement ( $row ; "artikalId" ) ;
	JSONGetElement ( $row ; "kalkulacijaId" ) ;
	$written + 1 ;
	JSONGetElement ( $row ; "sifra" ) ;
	JSONGetElement ( $row ; "naziv" ) ;
	JSONGetElement ( $row ; "jm" ) ;
	$kolicina ;
	$nabavna ;
	$nacin ;
	$staraBruto ;
	$staraNetoJed ;
	$stariPDV ;
	Round ( $staraBruto - $staraNetoJed ; 4 ) ;
	Round ( $staraNetoJed - $nabavna ; 4 ) ;
	$novaBruto ;
	$novaNetoJed ;
	$noviPDV ;
	Round ( $novaBruto - $novaNetoJed ; 4 ) ;
	Round ( $novaNetoJed - $nabavna ; 4 ) ;
	$staraVrij ;
	$staraVrijNeto ;
	$novaVrij ;
	$novaVrijNeto ;
	Round ( $novaVrij - $staraVrij ; 2 ) ;
	Round ( $novaVrijNeto - $staraVrijNeto ; 2 ) ;
	Round ( ( $novaVrij - $novaVrijNeto ) - ( $staraVrij - $staraVrijNeto ) ; 2 )
)

Response_SetData ( JSONSetElement ( "{}" ;
	[ "nivelacijaId" ; $nivelacijaId ; JSONString ] ;
	[ "brojNivelacije" ; $broj ; JSONString ] ;
	[ "brojStavki" ; $written ; JSONNumber ] ;
	[ "preskoceno" ; $skipped ; JSONNumber ]
) )
